import * as Stackit from "@alchemy.run/stackit";
import { expect } from "@alchemy.run/test";
import * as dns from "@distilled.cloud/stackit/dns";
import * as Provider from "alchemy/Provider";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import { logLevel, makeStackitTest, stackitEnvironment, stackitTags } from "../helpers.ts";

const { test } = makeStackitTest();

// DNS zones are billed per zone and month (a few cents pro rata for a test
// run), so the lifecycle runs ungated. Zone names are generated by the
// engine under `runs.onstackit.cloud` and are stable per stack/stage.
const options = { tags: stackitTags("dns", "zone"), timeout: 300_000 } as const;

/** Out-of-band zone state: the zone, or "gone" (typed NotFound or soft-deleted). */
const observeZone = (projectId: string, zoneId: string) =>
  dns.getZone({ projectId, zoneId }).pipe(
    Effect.map(({ zone }) => (zone.state === "DELETE_SUCCEEDED" ? ("gone" as const) : zone)),
    Effect.catchTag("NotFound", () => Effect.succeed("gone" as const)),
  );

/** Bounded wait (≤ ~90s) until the zone is gone. */
const waitUntilZoneGone = (projectId: string, zoneId: string) =>
  observeZone(projectId, zoneId).pipe(
    Effect.repeat({
      schedule: Schedule.spaced("3 seconds"),
      until: (zone) => zone === "gone",
      times: 30,
    }),
  );

const getZone = (projectId: string, zoneId: string) =>
  dns.getZone({ projectId, zoneId }).pipe(Effect.map(({ zone }) => zone));

const labelsOf = (zone: dns.Zone) => zone.labelsMap ?? {};

test.provider(
  "create, update and delete a zone",
  (stack) =>
    Effect.gen(function* () {
      const { projectId } = yield* stackitEnvironment;
      yield* stack.destroy();

      const created = yield* stack.deploy(
        Stackit.DNS.Zone("BasicZone", {
          description: "alchemy test zone",
          contactEmail: "hostmaster@example.com",
          defaultTTL: 3600,
          labels: { env: "test", keep: "yes" },
        }),
      );

      expect(created.zoneId).toEqual(expect.any(String));
      expect(created.projectId).toEqual(projectId);
      expect(created.dnsName).toMatch(/\.runs\.onstackit\.cloud$/);
      expect(created.name).toEqual(created.dnsName);
      expect(created.type).toEqual("primary");
      expect(["CREATE_SUCCEEDED", "UPDATE_SUCCEEDED"]).toContain(created.state);
      expect(created.defaultTTL).toEqual(3600);
      expect(created.description).toEqual("alchemy test zone");
      expect(created.labels).toEqual({ env: "test", keep: "yes" });
      expect(created.primaryNameServer.length).toBeGreaterThan(0);

      // Out of band: the zone exists with the desired settings and Alchemy's
      // ownership labels.
      const fetched = yield* getZone(projectId, created.zoneId);
      expect(fetched.dnsName.replace(/\.$/, "")).toEqual(created.dnsName);
      expect(fetched.defaultTTL).toEqual(3600);
      expect(fetched.contactEmail).toEqual("hostmaster@example.com");
      expect(labelsOf(fetched)).toMatchObject({
        env: "test",
        keep: "yes",
        "alchemy.id": "BasicZone",
      });

      // Redeploying unchanged is a no-op.
      const plan = yield* stack.plan(
        Stackit.DNS.Zone("BasicZone", {
          description: "alchemy test zone",
          contactEmail: "hostmaster@example.com",
          defaultTTL: 3600,
          labels: { env: "test", keep: "yes" },
        }),
      );
      expect(plan.resources.BasicZone).toMatchObject({ action: "noop" });

      // Update every mutable aspect in place.
      const updated = yield* stack.deploy(
        Stackit.DNS.Zone("BasicZone", {
          name: "alchemy-test-zone-updated",
          description: "alchemy test zone, updated",
          contactEmail: "dns-admin@example.com",
          defaultTTL: 7200,
          refreshTime: 7200,
          retryTime: 900,
          expireTime: 1209600,
          negativeCache: 120,
          labels: { env: "prod", role: "dns" },
        }),
      );

      expect(updated.zoneId).toEqual(created.zoneId);
      expect(updated.dnsName).toEqual(created.dnsName);
      expect(updated.name).toEqual("alchemy-test-zone-updated");
      expect(updated.defaultTTL).toEqual(7200);
      expect(updated.labels).toEqual({ env: "prod", role: "dns" });

      const refetched = yield* getZone(projectId, created.zoneId);
      expect(refetched.name).toEqual("alchemy-test-zone-updated");
      expect(refetched.description).toEqual("alchemy test zone, updated");
      expect(refetched.contactEmail).toEqual("dns-admin@example.com");
      expect(refetched.defaultTTL).toEqual(7200);
      expect(refetched.refreshTime).toEqual(7200);
      expect(refetched.retryTime).toEqual(900);
      expect(refetched.expireTime).toEqual(1209600);
      expect(refetched.negativeCache).toEqual(120);
      // The removed `keep` label is gone; ownership labels survive.
      expect(labelsOf(refetched)).toMatchObject({
        env: "prod",
        role: "dns",
        "alchemy.id": "BasicZone",
      });
      expect(labelsOf(refetched).keep).toBeUndefined();

      yield* stack.destroy();

      expect(yield* waitUntilZoneGone(projectId, created.zoneId)).toEqual("gone");
    }).pipe(logLevel),
  options,
);

test.provider(
  "changing the dnsName replaces the zone",
  (stack) =>
    Effect.gen(function* () {
      const { projectId } = yield* stackitEnvironment;
      yield* stack.destroy();

      const created = yield* stack.deploy(Stackit.DNS.Zone("ReplaceZone", {}));

      // Derive a second deterministic name from the generated one, keeping
      // the first label within 63 characters.
      const label = created.dnsName.split(".")[0]!;
      const replacementName = created.dnsName.replace(label, `${label.slice(0, 61)}-r`);

      const plan = yield* stack.plan(Stackit.DNS.Zone("ReplaceZone", { dnsName: replacementName }));
      expect(plan.resources.ReplaceZone).toMatchObject({ action: "replace" });

      const replaced = yield* stack.deploy(
        Stackit.DNS.Zone("ReplaceZone", { dnsName: replacementName }),
      );

      expect(replaced.zoneId).not.toEqual(created.zoneId);
      expect(replaced.dnsName).toEqual(replacementName);
      const fetched = yield* getZone(projectId, replaced.zoneId);
      expect(fetched.dnsName.replace(/\.$/, "")).toEqual(replacementName);

      // The old zone was deleted by the replacement.
      expect(yield* waitUntilZoneGone(projectId, created.zoneId)).toEqual("gone");

      yield* stack.destroy();

      expect(yield* waitUntilZoneGone(projectId, replaced.zoneId)).toEqual("gone");
    }).pipe(logLevel),
  options,
);

test.provider(
  "list enumerates the deployed zone",
  (stack) =>
    Effect.gen(function* () {
      const { projectId } = yield* stackitEnvironment;
      yield* stack.destroy();

      const deployed = yield* stack.deploy(Stackit.DNS.Zone("ListZone", { defaultTTL: 1800 }));

      const provider = yield* Provider.findProvider(Stackit.DNS.Zone);
      const all = yield* provider.list();
      const found = all.find((zone) => zone.zoneId === deployed.zoneId);
      expect(found?.dnsName).toEqual(deployed.dnsName);
      expect(found?.defaultTTL).toEqual(1800);
      expect(found?.projectId).toEqual(projectId);

      yield* stack.destroy();

      expect(yield* waitUntilZoneGone(projectId, deployed.zoneId)).toEqual("gone");
    }).pipe(logLevel),
  options,
);
